  const lg=(t+1)+'/'+ENGINE_TIERS.length+'  ·  ×'+E.push.toFixed(2);
  if(engVigCapEl)engVigCapEl.firstChild.nodeValue=TR(E.n);
  if(engVigTierEl)engVigTierEl.textContent=lg;
