  const ring=(r0,r1,k)=>{for(let j=0;j<NF;j++){const f0=j/NF*6.2832,f1=(j+1)/NF*6.2832;tr(k,P(f0,r0,0),P(f1,r0,0),P(f1,r1,0));tr(k,P(f0,r0,0),P(f1,r1,0),P(f0,r1,0));}};
  ring(.9,1,'ci1');ring(.84,.9,'ciW');
