    const q0=P(a0,.14,.012),q1=P(a1,.14,.012),r0=P(a0,.80,.012),r1=P(a1,.80,.012),rm=P(am,.82,.02),qm=P(am,.14,.02);
    const ma=P(a0*.7+am*.3,.5,.03),mb=P(a1*.7+am*.3,.5,.03),mm=P(am,.5,.045);
