  const fk=REDUCED_MOTION?Math.round((F.n-1)*.45):e<P.avant?0:e<P.avant+G?(e-P.avant)/F.ms:F.n-1;
  let k=Math.min(F.n-1,Math.floor(fk)),a=P.fondu&&k<F.n-1?Math.round((fk-k)*6)/6:0;if(a>=1){k++;a=0;}
