  let geo;try{const K=lpKit(Object.assign({},FRUIT_PAL,pal||{}));f(K);geo=K.done().f;}catch(e){return {err:'CONSTRUCTION : '+e.message};}
  if(!geo)return {err:'aucune facette en matière f'};
