  const m=new THREE.Mesh(geo,FRUIT_MAT);m.scale.setScalar(2.7);const vis=carGroup.visible;carGroup.visible=false;PHOTO.scene.add(m);
  const out={photos:[],facettes:Math.round(geo.attributes.position.count/3)};
