{const f9=function(c){return c.replace(/,([.\d]+)\)$/,function(m,a){return ','+(+a*PWR_BORD_K).toFixed(3)+')';});};PWR_DEFS.v.bd=f9(PWR_DEFS.v.fx);PWR_DEFS.v.bd2=f9(PWR_DEFS.v.fx2);}
{const st=document.createElement('style');st.textContent='#speedo.elec #speedVal,#speedo.elec #speedUnit{color:#7af0ff!important;text-shadow:0 0 6px #5ee6ff,0 0 2px #fff;animation:elecJit .1s steps(2) infinite}@keyframes elecJit{0%{transform:translate(0,0)}50%{transform:translate(1px,-1px)}100%{transform:translate(-1px,1px)}}';document.head.appendChild(st);}

/* ===== LE RAISIN ANGÉLIQUE : AIRTIME ×2, DOUBLE JAUGE (2026-10-20, Léo) =====
   Armé (14 s, il s'use au quart au sol : `pwrAirK`) le raisin ne rend plus l'airtime INFINI : il DOUBLE la jauge. Jauge 1 = l'airtime normal (6 s, 10,2 en orbite) ;
   quand elle est vide, la voiture PERD SES AILES D'ANGE (elles explosent en plumes, la caisse reste en vie) et la jauge 2 démarre, de même durée ; vide à son tour : explosion
   comme d'habitude. `RAI.stage` : 0 = jauge 1, 1 = jauge 2 (remis à 0 à chaque décollage, startFall). L'airtime PRÊTÉ par l'auto-école (`TUTO.pa`) reste infini.
   Les ailes blanches (sans halo : verdict de Léo) sont posées sur la caisse tant que le raisin est armé et que les ailes ne sont pas perdues.
   HUD : la barre du chrono de vol (#airHud) a une 2e barre, plus fine, dessous : la jauge 2. */
const RAI={stage:0,wings:null,vis:false};
function airDepasse(){ // la jauge est-elle vide ? (remplace `fallTR>airMax()&&pwrAirT<=0`)
  if(fallTR<=airMax())return false;
  if(pwrAirT>0){
    if(TUTO.pa)return false;                       // l'auto-école : airtime infini
    if(RAI.stage===0){RAI.stage=1;fallTR=0;airFlash=.6;raisinAilesBoom();return false;} // la 1re jauge est vide : les ailes explosent, la 2e démarre
  }
  return true;
}
const RAI_PLUME=function(K,sg,bx,by,bz,ang,L,W,cur,k1,k2,kT){
  const dx=sg*Math.cos(ang),dy=Math.sin(ang),px=-dy,py=dx*sg*sg,NS=7,pts=[],CUP=.42,FOLD=.5;
  for(let i=0;i<=NS;i++){const u=i/NS,l=L*u,cx=bx+dx*l+px*cur*l*u,cy=by+dy*l+py*cur*l*u,cz=bz+CUP*l*l*.5,hw=W*Math.pow(Math.sin(Math.PI*Math.pow(u,.72)),.62)+.004;
    pts.push({m:[cx,cy,cz+FOLD*hw*.6],l:[cx-px*hw,cy-py*hw,cz-FOLD*hw*.4],r:[cx+px*hw,cy+py*hw,cz-FOLD*hw*.4]});}
  for(let i=0;i<NS;i++){const A=pts[i],B=pts[i+1],kk=(i>=NS-2&&kT)?kT:null;
    K.tri(kk||k1,A.m,A.l,B.l);K.tri(kk||k1,A.m,B.l,B.m);K.tri(kk||k2,A.m,B.m,B.r);K.tri(kk||k2,A.m,B.r,A.r);}
};
function raisinAiles(){ // la paire d'ailes (une géométrie, trois rangs de plumes par aile), posée au-dessus des épaules de la caisse
  if(RAI.wings)return RAI.wings;
  const K=lpKit(FRUIT_PAL);
  for(const sg of [1,-1]){const bx=sg*.30,by=.36;
    for(let i=0;i<6;i++)RAI_PLUME(K,sg,bx,by,.02,.45+i*.2,.26+.03*Math.sin(i*1.3),.10,.10,'wgW','wgw',null);
    for(let i=0;i<6;i++)RAI_PLUME(K,sg,bx,by+.02,-.02,.35+i*.21,.42+.07*Math.sin(i*.9+.4),.11,.14,'wgW','wgw',null);
    for(let i=0;i<6;i++)RAI_PLUME(K,sg,bx,by+.04,-.06,.25+i*.22,.62+.12*Math.sin(i*.8+.3),.12,.16,'wgW','wgw','wgG');}
  const geo=K.done().f;if(!FRUIT_MAT){FRUIT_MAT=lpMat('f');FRUIT_MAT.userData.lp=0;}
  const m=new THREE.Mesh(geo,FRUIT_MAT);m.scale.setScalar(2.4);m.frustumCulled=false;
  const g=new THREE.Group();g.add(m);m.position.set(0,.55,-.2);g.visible=false;scene.add(g);RAI.wings=g;return g;
}
function raisinAilesBoom(){ // les ailes explosent en plumes : un flash blanc, une secousse, une gerbe qui part des épaules
  try{shake=Math.max(shake,.9);flashEcran('rgba(255,255,255,.75)');hap([20,40,30]);
    const p=crV1.copy(carGroup.position);p.y+=1.6;sparkBurst(sparkGold,p,26,13);sparkBurst(sparkBlue,p,16,9);
    if(SONV2)sfx('pwr.bouclierCasse');}catch(e){}
  RAI.vis=false;if(RAI.wings)RAI.wings.visible=false;
}
function raisinTick(dt){
  const arme=pwrAirT>0&&!TUTO.pa&&!(mode==='boom'||gameOver),vis=false&&arme&&RAI.stage===0; /* (2026-10-21, Léo : « enlève les ailes sur la voiture ») plus d'ailes visibles : la double jauge reste */
  if(vis||RAI.wings){const g=raisinAiles();if(g.visible!==vis)g.visible=vis;
    if(vis){g.position.copy(carGroup.position);g.quaternion.copy(carGroup.quaternion);const w=Math.sin(FAURAU.t*9)*.06;g.children[0].rotation.z=w*0+0;g.children[0].position.y=.55+Math.sin(FAURAU.t*5)*.05;}}
}
function raisinHud(double,fr2){ // la 2e barre sous le chrono de vol
  const el=raisinHud.el||(raisinHud.el=document.getElementById('airHud'));if(!el)return;
  if(!raisinHud.b){const bar=el.querySelector('.ahBar');if(!bar)return;const b2=bar.cloneNode(true);b2.classList.add('ahBar2');bar.after(b2);raisinHud.b=b2;
    const st=document.createElement('style');st.textContent='#airHud .ahBar2{display:none;height:9px;margin-top:3px;padding:2px}#airHud[data-d="1"] .ahBar2{display:block}#airHud .ahBar2 .ahF{width:calc(var(--a2,1)*100%);background:linear-gradient(90deg,#ff9ec2,#ffffff)}#airHud .ahBar2 .ahF::after{display:none}';document.head.appendChild(st);}
  const d=double?'1':'0';if(el.dataset.d!==d)el.dataset.d=d;
  if(double){const q=fr2.toFixed(2);if(raisinHud._q!==q){raisinHud._q=q;el.style.setProperty('--a2',q);}}
}
Object.assign(PWR_DEFS.a,{col:0xffffff,core:0xfff4e8,tint:'#ffd6f0',c2:'#d070d0',fx:'rgba(255,214,240,.8)',fx2:'rgba(208,112,208,.3)',msg:'🍇 RAISIN — AIRTIME ×2 : DEUX JAUGES !',sous:'AIRTIME x2, 2 JAUGES'});
Object.assign(I18N,{'PIMENT — NITRO INFINIE 7 s À FOND !':'CHILI — INFINITE NITRO 7 s FLAT OUT!','POMME DORÉE — LES PIÈCES VIENNENT À TOI !':'GOLDEN APPLE — THE COINS COME TO YOU!','FRUIT DU DRAGON — AURA ×2 · ×3 SI TU ENCHAÎNES !':'DRAGON FRUIT — AURA ×2 · ×3 IF YOU CHAIN!','⚡ CITRON — VITESSE ×2 — 8 s !':'⚡ LEMON — SPEED ×2 — 8 s!','🍇 RAISIN — AIRTIME ×2 : DEUX JAUGES !':'🍇 GRAPES — AIRTIME ×2: TWO GAUGES!'}); /* (24/10) les messages des fruits-pouvoirs en anglais (showMsg les passe par TR) */
{const f9=function(c){return c.replace(/,([.\d]+)\)$/,function(m,a){return ','+(+a*PWR_BORD_K).toFixed(3)+')';});};PWR_DEFS.a.bd=f9(PWR_DEFS.a.fx);PWR_DEFS.a.bd2=f9(PWR_DEFS.a.fx2);}
/* banc (dev) : `dbgRaisin()` l'état de la double jauge ; `dbgRaisin('vide')` vide la jauge en cours (pour voir les ailes exploser / la 2e jauge démarrer). */
window.dbgRaisin=function(k){if(k==='vide')fallTR=airMax()+.05;return {stage:RAI.stage,fallTR:+fallTR.toFixed(2),airMax:airMax(),pwrAirT:+pwrAirT.toFixed(2),mode:mode,ailes:!!(RAI.wings&&RAI.wings.visible)};};

/* ===== LA CHAUFFE DES SHADERS DES FRUITS (0 programme compilé en course) =====
   Quelques secondes après le chargement, au menu : un exemplaire de chaque fruit-pouvoir (et son aura), l'objet des éclairs, l'anneau de l'onde de choc et le disque du
   décor Genjutsu sont posés une fois dans la scène, compilés hors écran, puis retirés — le 1er citron de la partie ne fait pas saccader l'image. */
function fruitsChauffe(){
  if(fruitsChauffe.ok||(started&&!gameOver))return;fruitsChauffe.ok=true;
  try{const g=new THREE.Group();for(const k of ['n','v','x','a','m']){const m=mkPower(k,1);g.add(m);}
    if(!ZAP.grp)zapBuild();if(!DRG_DEC)dragonDecorBuild();
    scene.add(g);ZAP.ring.visible=true;ZAP.grp.visible=true;DRG_DEC.m.visible=true;raisinAiles().visible=true;
    renderer.compile(scene,camera);
    ZAP.ring.visible=false;ZAP.grp.visible=false;DRG_DEC.m.visible=false;raisinAiles().visible=false;scene.remove(g);}catch(e){}
}
setTimeout(fruitsChauffe,9000);
window.dbgChauffeFruits=function(){fruitsChauffe.ok=false;const n0=renderer.info.programs?renderer.info.programs.length:0;fruitsChauffe();return {avant:n0,apres:renderer.info.programs?renderer.info.programs.length:0};};

/* ===== LES FRUITS-POUVOIRS POSÉS AU SOL (2026-10-20, Léo : « posés par terre, qu'ils ne flottent pas ; l'animation au sol, qui sort un peu du sol autour ; il faut qu'on VOIE le fruit ») =====
   Le fruit repose sur la route. Autour de lui, SANS le cacher : un CYLINDRE OUVERT (rayon > fruit, 3,4 m de haut) dont le shader dessine l'aura qui sort du sol et se dissout vers le haut
   (feu, éclairs, bandes hypnotiques, brume, étincelles) + un DISQUE posé sur la route (le Sharingan Genjutsu à plat pour le dragon, un anneau lumineux pour les autres).
   Les deux ne sont pas mis à l'échelle du fruit (dimensions en mètres) ; leur matière est partagée (`FAURAU.uT`) : zéro travail par fruit. */
const FSOL_VS=`uniform float uH;varying vec3 vP;varying float vH;varying float vA;
void main(){vP=position;vH=clamp((position.y+uH*.5)/uH,0.,1.);vA=atan(position.z,position.x);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`;
const FSOL_FS=`uniform float uT,uKind;varying vec3 vP;varying float vH;varying float vA;
`+FSH2_NOISE+`
void main(){float h=vH;vec4 col=vec4(0.);vec3 q=vec3(cos(vA)*2.4,h*2.6-uT*(uKind<.5?2.1:.8),sin(vA)*2.4);
  float f=n3(q)*.6+n3(q*2.1+7.)*.4;
  if(uKind<.5){float m=smoothstep(.18,.5,f+(1.-h)*.95-.5);
    vec3 c=mix(vec3(.85,.1,.04),vec3(1.,.62,.12),smoothstep(.3,.55,f+(1.-h)*.2));c=mix(c,vec3(1.,.96,.66),smoothstep(.62,.85,f+(1.-h)*.25));
    col=vec4(c,m*(1.-h*h)*.95);}
  else if(uKind<1.5){float line=pow(1.-abs(2.*f-1.),12.)+.7*pow(1.-abs(2.*n3(q*2.3+3.)-1.),16.);float flick=step(.22,fract(sin(floor(uT*13.)*91.7)*437.5));
    float a=clamp((line*flick+(1.-h)*.18)*pow(1.-h,1.4)*1.3,0.,1.);col=vec4(mix(vec3(.4,.9,1.),vec3(1.,1.,.8),clamp(line,0.,1.)),a);}
  else if(uKind<2.5){float b=.5+.5*sin(vA*4.-h*8.+uT*3.2);vec3 c=.55+.45*cos(6.2832*(vec3(0.,.2,.4)+.5*b+uT*.1));c=mix(c,vec3(.9,.1,.35),.4);
    col=vec4(c,(b*.6+f*.3)*pow(1.-h,1.5)*1.2);}
  else if(uKind<3.5){col=vec4(1.,.92,.97,f*pow(1.-h,1.6)*.8);}
  else{float sp=step(.955,n3(q*5.+vec3(0.,floor(uT*6.),0.)));col=vec4(mix(vec3(1.,.78,.25),vec3(1.,.95,.7),sp),clamp((.28*(1.-h)+sp)*pow(1.-h,.8),0.,1.));}
  if(col.a<.02)discard;gl_FragColor=col;}`;
const FSOLD_VS=`varying vec2 vUv;void main(){vUv=position.xy*2.;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`;
const FSOLD_FS=`uniform float uT,uKind;varying vec2 vUv;
float rn(float x){return fract(sin(x*127.1)*43758.5453);}
void main(){vec2 p=vUv;float r=length(p);if(r>1.)discard;float a=atan(p.y,p.x);vec4 col=vec4(0.);
  if(uKind<.5){ // PIMENT : une ÉTOILE DE FLAMMES — huit langues qui ondulent, blanc-jaune au coeur, rouge aux pointes
    float tip=.5+.5*cos(8.*a+uT*2.2+sin(r*9.-uT*5.)*.5);float rf=.34+.6*pow(tip,2.2);
    float inside=1.-smoothstep(rf-.03,rf,r);float k=r/max(rf,.01);
    vec3 c=mix(vec3(1.,.95,.6),vec3(1.,.5,.1),smoothstep(0.,.55,k));c=mix(c,vec3(.8,.08,.03),smoothstep(.6,1.,k));
    col=vec4(c,inside*.92);}
  else if(uKind<1.5){ // CITRON : des ÉCLATS DE FOUDRE — six rayons brisés qui claquent, un hexagone qui vibre, un noyau blanc
    float stp=floor(uT*13.);float aa=a+sin(r*14.+stp*3.1)*.13;
    float d=abs(fract(aa*6./6.2832+.5)-.5)*6.2832/6.*r;float ray=1.-smoothstep(0.,.05,d);
    float flick=step(.2,fract(sin(stp*91.7)*437.5));
    float hex=1.-smoothstep(0.,.035,abs(r-.38-.03*sin(uT*30.)));float core=1.-smoothstep(.12,.19,r);
    float al=(ray*flick*(.45+.55*r)+hex*.85+core)*(1.-smoothstep(.88,1.,r));
    col=vec4(mix(vec3(.4,.9,1.),vec3(1.,1.,.85),clamp(ray+core,0.,1.)),clamp(al,0.,1.));}
  else if(uKind<3.5){ // RAISIN : DEUX AILES déployées de chaque côté — trois paquets de plumes, un point de nacre au centre
    vec2 q=vec2(abs(p.x)-.1,p.y*1.15);float r2=length(q),a2=atan(q.y,q.x);
    float L=.92-.4*abs(a2)+.05*sin(a2*20.);
    float feather=step(.16,fract(a2*3.2+.5))*(1.-smoothstep(L-.035,L,r2))*step(.12,r2)*step(abs(a2),1.15);
    float body=1.-smoothstep(.07,.13,r);
    col=vec4(mix(vec3(.86,.78,.96),vec3(1.),r2/L),clamp(feather*.88+body*.5,0.,1.)*(.86+.14*sin(uT*3.+r2*8.)));}
  else{ // POMME DORÉE : un AIMANT EN FER À CHEVAL d'or, pointes rouge et blanc, des arcs de champ qui se resserrent vers lui
    vec2 m=vec2(p.x,-p.y);float rr=length(m);
    float arc=step(0.,m.y)*step(.38,rr)*(1.-smoothstep(.62,.66,rr));
    float leg=step(.38,abs(m.x))*(1.-smoothstep(.62,.66,abs(m.x)))*step(m.y,0.)*step(-.66,m.y);
    float body=clamp(arc+leg,0.,1.);float tipz=step(m.y,-.46)*leg;
    vec3 c=mix(vec3(1.,.74,.2),vec3(1.,.95,.7),smoothstep(.45,.62,rr));c=mix(c,mix(vec3(.9,.12,.12),vec3(.96),step(m.y,-.56)),tipz);
    float fld=1.-smoothstep(0.,.025,abs(r-(1.-fract(uT*.45))*.92-.06));
    col=vec4(c,clamp(body*.95+fld*.45*(1.-body),0.,1.));}
  if(col.a<.02)discard;gl_FragColor=col;}`;
let FSOL_GEO=null,FSOLD_GEO=null;
function fauraSol(kind){ // kind : 0 piment · 1 citron · 2 dragon · 3 raisin · 4 pomme dorée — dans le repère de la route : +y = le haut, le sol à y = 0
  const g=new THREE.Group(),R=5.6,H=3.8;
  const cm=new THREE.ShaderMaterial({uniforms:{uT:FAURAU.uT,uKind:{value:kind},uH:{value:H}},vertexShader:FSOL_VS,fragmentShader:FSOL_FS,transparent:true,depthWrite:false,side:THREE.BackSide}); // BackSide : seule la paroi du FOND est dessinée — l'aura est DERRIÈRE et AUTOUR du fruit, jamais devant (on le voit toujours)
  const c=new THREE.Mesh(FSOL_GEO||(FSOL_GEO=new THREE.CylinderGeometry(R,R*.86,H,40,1,true)),cm);c.position.y=H*.5;c.renderOrder=21;g.add(c);
  const dm=kind===2?new THREE.ShaderMaterial({uniforms:{uT:FAURAU.uT,uA:{value:.9}},vertexShader:FSOLD_VS,fragmentShader:FDISC_FS,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-3,polygonOffsetUnits:-3})
    :new THREE.ShaderMaterial({uniforms:{uT:FAURAU.uT,uKind:{value:kind}},vertexShader:FSOLD_VS,fragmentShader:FSOLD_FS,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-3,polygonOffsetUnits:-3});
  const d=new THREE.Mesh(FSOLD_GEO||(FSOLD_GEO=new THREE.PlaneGeometry(1,1)),dm);d.rotation.x=-Math.PI/2;d.position.y=.08;d.scale.setScalar(R*2.9);d.renderOrder=20;g.add(d);
  return g;
}
/* banc (dev) : `dbgPwrPhoto(k, t, dist, haut)` — pose le fruit-pouvoir `k` 20 m devant la caisse, EN SITUATION (le vrai mkPower : posé au sol, l'aura qui en sort), place la caméra derrière lui à `dist` m, `haut` m au-dessus,
   fige l'aura au temps `t` et rend UNE image du vrai jeu (pause). Rend la dataURL. */
window.dbgPwrPhoto=function(k,t,dist,haut){
  if(window.__pp){scene.remove(window.__pp);window.__pp=null;}
  if(started&&!gameOver&&!paused)togglePause();
  const sp=s+20;frameAt(sp,F);mat4b.makeBasis(F.b,F.n,F.t);
  const m=mkPower(k,1),lev9=m.userData.lev||2.1;m.position.copy(F.p).addScaledVector(F.n,lev9);m.quaternion.setFromRotationMatrix(mat4b);m.updateMatrix();m.updateMatrixWorld(true);scene.add(m);window.__pp=m;
  FAURAU.uT.value=t||0;
  const c=new THREE.Vector3().copy(F.p).addScaledVector(F.t,-(dist||14)).addScaledVector(F.n,haut||4.5).addScaledVector(F.b,2.5);
  camera.position.copy(c);camera.lookAt(F.p.x+F.n.x*3,F.p.y+F.n.y*3,F.p.z+F.n.z*3);camera.updateMatrixWorld();
  RIM_U.uSunV.value.copy(RIM_DIR).transformDirection(camera.matrixWorldInverse);
  if(POST_ON&&composer)composer.render();else renderer.render(scene,camera);
  return renderer.domElement.toDataURL('image/png');
};

/* ===== LES AURAS EN MINI CUBES, AUTOUR DU FRUIT (2026-10-20, v750, Léo : « utilise des mini cubes… ») =====
   Le fruit est posé au sol ; l'aura vit AUTOUR de lui (rayon > son encombrement) et ne le cache jamais.
   · PIMENT : de belles FLAMMES en cubes — huit langues qui dansent autour, blanc-jaune → orange → rouge, dont les cubes se DÉSINTÈGRENT en montant (plus haut, plus de cubes éteints) + des braises qui s'échappent.
   · CITRON : des ÉCLAIRS DROITS (rubans de segments rectilignes, angles vifs, jamais de courbe) qui TOURNENT autour du fruit puis s'ÉCHAPPENT vers l'extérieur ; ils claquent 13 fois par seconde.
   · DRAGON : un tourbillon de mini cubes TOUT AUTOUR, qui montent du sol — rouge, violet, rose, vert, bleu (par petits groupes, pas un arc-en-ciel) — et évitent le fruit.
   · RAISIN : un VENT très léger qui tourne autour (poussière claire et quelques cubes pâles, trajets irréguliers : jamais des lignes ni des formes qui se suivent). Rien au sol.
   · POMME DORÉE : rien autour ; le fruit lui-même SCINTILLE plus (coque d'étincelles, reflet qui balaie), plus lisse, plus brillant, un peu plus de rouge dans l'or.
   Matières et géométries PARTAGÉES par pouvoir (un seul exemplaire de chaque, tout le mouvement dans le vertex shader) ; `uG` = la hauteur du sol sous le centre du fruit. */
FAURAU.uPx={value:700};
const FCUB_VS=`uniform float uT,uPx,uG,uKind;attribute vec4 aSeed;varying vec4 vCol;varying float vShape;
float h(float x){return fract(sin(x*127.1)*43758.5453);}
void main(){vec3 p=vec3(0.);float size=0.;vec4 col=vec4(0.);float shape=0.;vec4 s=aSeed;
  if(uKind<.5){ // PIMENT
    if(s.x<1.5){float tg=floor(s.x*8.+.01);float u=s.y;float ang=tg*.7854+h(tg)*.3+sin(uT*.8+tg)*.15;
      float H=2.4+2.4*(.5+.5*sin(uT*(2.+h(tg+9.)*2.)+tg*2.3));float hh=u*H;
      float rr=4.5+.5*sin(uT*1.7+tg)+hh*.14*sin(uT*3.+tg*5.+u*4.);float a2=ang+hh*.1*sin(uT*2.+tg);
      p=vec3(cos(a2)*rr,uG+.2+hh,sin(a2)*rr);
      float stp=floor(uT*7.+s.z*40.);float alive=step(u*.88,h(s.w*50.+stp)); // la désintégration : plus on monte, moins de cubes restent
      size=(.78-.5*u)*alive;
      vec3 c=u<.2?vec3(1.,.97,.7):u<.5?vec3(1.,.62,.14):u<.8?vec3(1.,.3,.06):vec3(.7,.1,.04);col=vec4(c,alive);}
    else{float life=fract(uT*(.35+.3*s.z)+s.w);float ang=s.y*6.2832+uT*.6;float rr=4.3+s.z*1.5;
      p=vec3(cos(ang)*rr,uG+life*4.6,sin(ang)*rr);p.x+=sin(uT*3.+s.y*20.)*.3*life;size=.36*(1.-life);col=vec4(mix(vec3(1.,.7,.2),vec3(.8,.12,.05),life),1.-life);}}
  else if(uKind<2.5){ // DRAGON : le tourbillon
    float life=fract(uT*(.14+.1*s.z)+s.w);float ang=s.x*6.2832+uT*(.35+.3*s.y)*(s.y<.5?1.:-.6)+life*1.5;
    float rr=4.4+s.z*2.3+.5*sin(uT*1.3+s.x*30.);p=vec3(cos(ang)*rr,uG+.25+life*5.5,sin(ang)*rr);
    size=(.5-.3*life)*(.6+.8*s.y);float k=h(s.x*91.);
    vec3 c=k<.28?vec3(.95,.1,.2):k<.52?vec3(.55,.2,.95):k<.72?vec3(1.,.35,.75):k<.86?vec3(.3,.9,.35):vec3(.25,.5,1.);
    col=vec4(c,(1.-life*.7)*smoothstep(0.,.08,life));}
  else{ // RAISIN : le vent léger
    float life=fract(uT*(.2+.25*s.z)+s.w);float ang=s.x*6.2832+uT*(.5+.5*s.y)+sin(uT*.9+s.x*40.)*.6+life*2.;
    float rr=4.3+s.z*2.3+.6*sin(uT*1.1+s.y*20.+life*5.);float y=.5+life*3.7+.5*sin(uT*1.7+s.x*50.);
    p=vec3(cos(ang)*rr,uG+y,sin(ang)*rr);float cube=step(.8,s.y);size=(cube>.5?.2:.5+.5*s.y)*(1.-.4*life);shape=cube>.5?0.:3.;
    col=vec4(mix(vec3(1.,.97,1.),vec3(.95,.86,1.),s.z),(cube>.5?.8:.34)*sin(life*3.1416));}
  vCol=col;vShape=shape;vec4 mv=modelViewMatrix*vec4(p,1.);gl_Position=projectionMatrix*mv;
  if(col.a<.02||size<.01)gl_Position=vec4(9.,9.,9.,1.);
  gl_PointSize=clamp(size*uPx/max(.1,-mv.z),1.5,70.);}`;
const FCUB_FS=`varying vec4 vCol;varying float vShape;
void main(){vec2 c=gl_PointCoord-.5;
  if(vShape>2.5){float r=length(c)*2.;float al=smoothstep(1.,.2,r)*vCol.a;if(al<.01)discard;gl_FragColor=vec4(vCol.rgb,al);return;}
  float v=max(abs(c.x),abs(c.y))*2.;vec3 core=min(vCol.rgb*1.2+.1,vec3(1.));vec3 edge=vCol.rgb*vec3(.8,.55,.65);
  gl_FragColor=vec4(v>.7?edge:core,clamp(vCol.a,0.,1.));}`;
const FCUB_N={0:190,2:170,3:80},FCUB={mat:{},geo:{}};
function fcubGeo(kind){
  if(FCUB.geo[kind])return FCUB.geo[kind];
  const n=FCUB_N[kind],pos=new Float32Array(n*3),sd=new Float32Array(n*4);let q=kind*4421+31;const r=()=>{q=(q*16807)%2147483647;return q/2147483647;};
  for(let i=0;i<n;i++){sd[i*4]=r();sd[i*4+1]=r();sd[i*4+2]=r();sd[i*4+3]=r();
    if(kind===0){if(i<8*14){sd[i*4]=Math.floor(i/14)/8;sd[i*4+1]=(i%14)/13;}else sd[i*4]=2;}}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(pos,3));g.setAttribute('aSeed',new THREE.BufferAttribute(sd,4));
  g.boundingSphere=new THREE.Sphere(new THREE.Vector3(0,2,0),12);FCUB.geo[kind]=g;return g;
}
function fcubMat(kind,uG){
  const k=kind+':'+uG.toFixed(2);if(FCUB.mat[k])return FCUB.mat[k];
  return FCUB.mat[k]=new THREE.ShaderMaterial({uniforms:{uT:FAURAU.uT,uPx:FAURAU.uPx,uG:{value:uG},uKind:{value:kind}},vertexShader:FCUB_VS,fragmentShader:FCUB_FS,transparent:true,depthWrite:false});
}
/* les ÉCLAIRS DROITS du citron : des rubans de segments RECTILIGNES (angles vifs), autour du fruit puis qui s'échappent */
const FZ_NB=7,FZ_NS=6;
const FZ_VS=`uniform float uT,uG,uPx;attribute vec3 aSeg;varying float vA;varying float vK;
float h(float x){return fract(sin(x*127.1)*43758.5453);}
vec3 pt(float bolt,float stp,float k){float th0=h(bolt*5.1+stp*.37)*6.2832+uT*.9;float th=th0+k*.34;
  float zz=(h(k*7.7+bolt*3.3+stp*1.9)-.5);float rr=4.4+zz*1.3+max(0.,k-4.)*1.6;float yy=.7+1.1*k*h(bolt+2.)+(h(k*3.1+bolt*9.+stp)-.5)*1.6;
  if(k>4.5)yy+=1.6;return vec3(cos(th)*rr,uG+yy,sin(th)*rr);}
void main(){float bolt=aSeg.x,k=aSeg.y,side=aSeg.z;float stp=floor(uT*13.+bolt*3.7);float on=step(.3,h(bolt*17.1+stp*1.3));
  vec3 p=pt(bolt,stp,k),pn=pt(bolt,stp,min(5.,k+1.));vec4 mv=modelViewMatrix*vec4(p,1.);vec3 dv=(modelViewMatrix*vec4(pn,1.)).xyz-mv.xyz;
  vec3 sd=normalize(cross(dv,vec3(0.,0.,1.))+vec3(1e-4));mv.xyz+=sd*side*.1;gl_Position=projectionMatrix*mv;vA=on*(1.-.35*k/5.);vK=h(bolt+stp*.37);}`;
const FZ_FS=`varying float vA;varying float vK;void main(){if(vA<.01)discard;gl_FragColor=vec4(mix(vec3(.45,.92,1.),vec3(1.,1.,.82),vK),vA);}`;
let FZ_GEO=null,FZ_MAT={};
function fzGeo(){
  if(FZ_GEO)return FZ_GEO;const nv=FZ_NB*(FZ_NS)*2,pos=new Float32Array(nv*3),sg=new Float32Array(nv*3),ix=[];let v=0;
  for(let b=0;b<FZ_NB;b++){const base=v;for(let k=0;k<FZ_NS;k++)for(const c of [-1,1]){sg[v*3]=b;sg[v*3+1]=k;sg[v*3+2]=c;v++;}
    for(let k=0;k<FZ_NS-1;k++){const a=base+k*2;ix.push(a,a+1,a+2,a+1,a+3,a+2);}}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(pos,3));g.setAttribute('aSeg',new THREE.BufferAttribute(sg,3));g.setIndex(ix);
  g.boundingSphere=new THREE.Sphere(new THREE.Vector3(0,2,0),14);return FZ_GEO=g;
}
function fzMat(uG){const k=uG.toFixed(2);return FZ_MAT[k]||(FZ_MAT[k]=new THREE.ShaderMaterial({uniforms:{uT:FAURAU.uT,uG:{value:uG},uPx:FAURAU.uPx},vertexShader:FZ_VS,fragmentShader:FZ_FS,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide}));}
/* fauraCubes(kind, lev) : l'aura d'un fruit-pouvoir, dans le repère du groupe (centre du fruit) ; `lev` = hauteur du centre au-dessus du sol. kind : 0 piment · 1 citron · 2 dragon · 3 raisin · (4 pomme dorée : voir mkPower) */
function fauraCubes(kind,lev){
  const g=new THREE.Group(),uG=-lev;
  if(kind===1){const m=new THREE.Mesh(fzGeo(),fzMat(uG));m.renderOrder=22;g.add(m);}
  else if(kind===0||kind===2||kind===3){const m=new THREE.Points(fcubGeo(kind),fcubMat(kind,uG));m.renderOrder=22;g.add(m);}
  return g;
}

// la POMME DORÉE : un peu plus de rouge dans l'or (contraste), toujours DORÉE
FRUIT_PAL.go1={g:'f',c:0xc89012};FRUIT_PAL.go2={g:'f',c:0xf0bc30};FRUIT_PAL.go3={g:'f',c:0x8a3c0c};FRUIT_PAL.goH={g:'f',c:0xfff2b0};
/* ===== LE FINAL SPIN v2 (2026-10-14 soir — Sacha, sur la v1 : « c'est ÇA la roulette, sérieux ? » ; l'ordre du matin : « le final spin [de
   Jetpack Joyride] … la bonne DA, HUD, lumières, bonnes animations et un vrai niveau de finition ; ça ne doit pas se déclencher à chaque
   partie ») — session IDEE. La v1 (une petite grille d'icônes sur l'écran de mort en transparence) est REFAITE :
   · UNE GRANDE MACHINE qui tient l'écran, en relief : enseigne lumineuse « FINAL SPIN », caisse en laque cerclée d'or, ampoules qui chassent,
     vitre aux rouleaux IVOIRE (des cylindres : les symboles s'écrasent et s'éteignent vers le haut et le bas), ligne de gain néon, un écran de
     lots sous la vitre, un GROS LEVIER à boule rouge sur le flanc. Le fond est OPAQUE (plus rien de l'écran de mort ne transparaît).
   · LE LEVIER SE TIRE AU DOIGT : il suit le pouce vers le bas avec une résistance qui monte, cliquette au cran (passé 55 %), part en
     tirage au lâcher et revient en ressort ; lâché trop tôt, il remonte sans rien tirer. Un toucher simple, ou TIRER (l'unique or), le tirent
     d'un coup. Les jetons attendent sur un PLATEAU (des pièces à couronne) : il n'y a plus de compteur « ×0 ».
   · LES ROULEAUX : l'élan (un cran en arrière), la course (19 symboles/s, filé : les symboles s'étirent), la pose un par un avec du poids
     (easeOutBack raccordée à la vitesse), le 3e qui fait durer le suspense quand les deux premiers sont pareils (ampoules en folie).
   · LES LOTS SONT LES SYMBOLES (`SPIN.lots`, une ligne par lot, réglée par GENERAL) : trois PETITS SACS, trois SACS, trois GROS SACS (de
     l'argent du jeu), trois CŒURS = une SECONDE CHANCE GRATUITE (un bon `SAVE.d.chanceG`, servi par l'offre de GENERAL à la prochaine
     explosion), trois ÉCLAIRS = un DÉPART BOOSTÉ (`SAVE.d.spinBoost` : la partie suivante part nitro pleine, moteur au palier 1), trois
     JETONS = un tirage de plus, trois 7 = le JACKPOT (flash à 3 éclats par seconde au plus, pluie de billets, pièces, vibration). Sans
     brelan : un lot de consolation. Symboles en pixel art de couleur (`SPIN_SPR`, peints une fois dans des canvas).
   · Sons de la session SON : spin.levier, spin.cran, spin.arret (une note par rouleau), spin.piece, spin.gain, spin.jackpot.
   · INCHANGÉ depuis la v1 : les jetons rares sur la route (spinPose / spinPrend / mkJeton), gardés dans `SAVE.d.spinJ`, la machine qui
     s'ouvre sur l'écran de fin après l'offre de seconde chance (`chanceAttend()`), `?spin=0`, `dbgSpin(n,lot)` (lot = un id de SPIN.lots,
     'rien', ou les anciens 'jackpot'/'brelan'/'paire'), `dbgJeton(d)`. */
Object.assign(I18N,{'FINAL SPIN':'FINAL SPIN','JETON SPIN':'SPIN TOKEN','TIRER':'PULL','CONTINUER':'CONTINUE','JACKPOT !':'JACKPOT!',
  'PETIT SAC':'SMALL BAG',"SAC D'ARGENT":'MONEY BAG','GROS SAC':'BIG BAG','SECONDE CHANCE GRATUITE':'FREE SECOND CHANCE','DÉPART BOOSTÉ':'BOOSTED START',
  '+1 JETON':'+1 TOKEN','LOT DE CONSOLATION':'CONSOLATION PRIZE','TIRE LE LEVIER':'PULL THE LEVER','À TA PROCHAINE CHUTE':'ON YOUR NEXT CRASH',
  'NITRO PLEINE · MOTEUR +1':'FULL NITRO · ENGINE +1','UN TIRAGE DE PLUS':'ONE MORE PULL','GRATUIT':'FREE','À LA PROCHAINE PARTIE':'ON YOUR NEXT RUN',
  'VOITURE ÉPIQUE':'EPIC CAR'}); // (2026-10-19) le jackpot donne une caisse
