    try{if(SONV2)sfx(tri?'pwr.triple':'pwr.double');else{chimeNote(noteP(4,1),.2,.06,.3);chimeNote(noteP(7,1),.28,.06,.34);if(tri)chimeNote(noteP(11,1),.36,.07,.45);}}catch(e){} // la session SON sonorise ; sinon le carillon de repli
