  windG=AC.createGain();windG.gain.value=0;
  wsrc.connect(windF);windF.connect(windG);windG.connect(MASTER);wsrc.start();
  // CRISSEMENT v2 : deux bandes résonantes non harmoniques (950/1480 Hz) + LFO de STICK-SLIP
